    {"id": "c", "symbol": "right-hand side", "value": 6, "provenance": "given"},
    {"id": "m", "symbol": "boundary slope", "value": -0.6666666666666666, "provenance": "derived", "dependsOn": ["a", "b"]},
    {"id": "xi", "symbol": "x-intercept", "value": -3, "provenance": "derived", "dependsOn": ["a", "c"]},
    {"id": "yi", "symbol": "y-intercept", "value": -2, "provenance": "derived", "dependsOn": ["b", "c"]}
  ],
  "entities": [
    {"id": "axes", "kind": "axes"},
    {"id": "boundary", "kind": "polyline", "role": "included boundary", "label": "-2x-3y=6"},
    {"id": "xIntercept", "kind": "point", "role": "x-intercept", "label": "(-3,0)"},
    {"id": "yIntercept", "kind": "point", "role": "y-intercept", "label": "(0,-2)"},
    {"id": "origin", "kind": "point", "role": "test point", "label": "(0,0)"},
    {"id": "solutionRegion", "kind": "polygon", "role": "solution half-plane"}
  ],
  "constructions": [
    {"id": "makeAxes", "operator": "axes", "inputs": {"xMin": -5, "xMax": 3, "yMin": -4, "yMax": 4}, "outputs": ["axes"]},
    {"id": "makeBoundary", "operator": "function_curve", "inputs": {"expression": "-2-(2/3)*x", "variable": "x", "xMin": -5, "xMax": 3}, "outputs": ["boundary"]},
    {"id": "makeXIntercept", "operator": "point", "inputs": {"x": -3, "y": 0, "coordinateSpace": "world"}, "outputs": ["xIntercept"]},
    {"id": "makeYIntercept", "operator": "point", "inputs": {"x": 0, "y": -2, "coordinateSpace": "world"}, "outputs": ["yIntercept"]},
    {"id": "makeOrigin", "operator": "point", "inputs": {"x": 0, "y": 0, "coordinateSpace": "world"}, "outputs": ["origin"]},
    {"id": "makeSolutionRegion", "operator": "constraint_region", "inputs": {"constraints": [{"expression": "-2*x-3*y-6", "relation": "le"}], "xMin": -5, "xMax": 3, "yMin": -4, "yMax": 4}, "outputs": ["solutionRegion"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "xInterceptOnBoundary", "predicate": "function_value", "entities": ["boundary"], "expected": {"x": -3, "y": 0}, "severity": "fatal"},
    {"id": "yInterceptOnBoundary", "predicate": "function_value", "entities": ["boundary"], "expected": {"x": 0, "y": -2}, "severity": "fatal"}
  ],
