    {"id": "boundaryIncluded", "kind": "callout", "targetIds": ["boundary"], "text": "Use a solid boundary: equality is included."},
    {"id": "testOrigin", "kind": "callout", "targetIds": ["origin"], "text": "Test (0,0): 0 ≤ 6 is true."},
    {"id": "shadeSide", "kind": "highlight", "targetIds": ["solutionRegion"], "text": "Shade the side containing the origin, on or above the boundary."}
  ],
  "requiredEntityIds": ["axes", "boundary", "xIntercept", "yIntercept", "origin", "solutionRegion"],
  "revealGroups": [
    {"id": "setup", "entityIds": ["axes", "boundary"], "dependsOn": [], "narrationCue": "Start with the equality as the boundary."},
    {"id": "intercepts", "entityIds": ["xIntercept", "yIntercept"], "dependsOn": ["setup"], "narrationCue": "The intercepts are (-3,0) and (0,-2); equality makes the line solid."},
    {"id": "test", "entityIds": ["origin"], "dependsOn": ["intercepts"], "narrationCue": "Test the origin: 0 ≤ 6 is true."},
    {"id": "shade", "entityIds": ["solutionRegion"], "dependsOn": ["test"], "narrationCue": "Shade the half-plane containing the origin, including the boundary."}
  ],
  "teachingTimeline": [
    {"id": "showSetup", "revealGroupId": "setup"},
