    {"id": "g1", "symbol": "x coefficient", "value": 3, "provenance": "given", "sourceText": "g1 = 3"},
    {"id": "g2", "symbol": "y coefficient", "value": -2, "provenance": "given", "sourceText": "g2 = -2"},
    {"id": "g3", "symbol": "right-hand side", "value": 4, "provenance": "given", "sourceText": "g3 = 4"}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "coordinate plane"},
    {"id": "boundary", "kind": "polyline", "role": "excluded boundary", "label": "3x-2y=4"},
    {"id": "shaded_side", "kind": "polygon", "role": "solution side", "label": "3x-2y>4"}
  ],
  "constructions": [
    {
      "id": "make_axes",
      "operator": "axes",
      "inputs": {"xMin": -3, "xMax": 3, "yMin": -5, "yMax": 4},
      "outputs": ["axes"]
    },
    {
      "id": "make_boundary",
      "operator": "function_curve",
      "inputs": {"expression": "(3*x-4)/2", "variable": "x", "xMin": -2, "xMax": 3},
      "outputs": ["boundary"]
    },
    {
      "id": "make_shaded_side",
      "operator": "constraint_region",
      "inputs": {
        "constraints": [{"expression": "3*x-2*y-4", "relation": "ge"}],
        "xMin": -3,
        "xMax": 3,
        "yMin": -5,
        "yMax": 4
      },
      "outputs": ["shaded_side"]
    }
  ],
  "relations": [],
  "assertions": [
    {
      "id": "boundary_value",
      "predicate": "function_value",
      "entities": ["boundary"],
      "expected": {"x": 0, "y": -2},
      "severity": "fatal"
    }
  ],
  "annotations": [
    {
      "id": "boundary_exclusion",
      "kind": "callout",
      "targetIds": ["boundary"],
      "text": "Draw this line dashed: equality is excluded by the strict inequality."
    },
    {
      "id": "shade_explanation",
      "kind": "callout",
      "targetIds": ["shaded_side"],
      "text": "Shade below the line: dividing by −2 reverses the inequality, so y < (3/2)x − 2."
    }
  ],
  "requiredEntityIds": ["axes", "boundary", "shaded_side"],
  "revealGroups": [
    {
      "id": "setup",
      "entityIds": ["axes", "boundary"],
      "dependsOn": [],
      "narrationCue": "Replace > with = to locate the boundary. The strict inequality excludes points on it, so draw it dashed."
    },
    {
      "id": "shade",
      "entityIds": ["shaded_side"],
      "dependsOn": ["setup"],
      "narrationCue": "Dividing by negative two reverses the inequality. Shade the side below the dashed line."
    }
  ],
  "teachingTimeline": []
}

